// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAccounts List owned user accounts with exact ledger balances
	// (GET /api/v1/accounts)
	ListAccounts(w http.ResponseWriter, r *http.Request, params ListAccountsParams)
	// CreateAccount Create an account and optionally post its opening balance atomically
	// (POST /api/v1/accounts)
	CreateAccount(w http.ResponseWriter, r *http.Request)
	// UpdateAccount Rename, archive, restore, or change an unused account currency
	// (PATCH /api/v1/accounts/{accountId})
	UpdateAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// Login Authenticate with email and password
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// VerifyLoginRecoveryCode Complete a password login with a one-time recovery code
	// (POST /api/v1/auth/login/recovery)
	VerifyLoginRecoveryCode(w http.ResponseWriter, r *http.Request)
	// VerifyLoginTOTP Complete a password login with an authenticator code
	// (POST /api/v1/auth/login/totp)
	VerifyLoginTOTP(w http.ResponseWriter, r *http.Request)
	// Logout Revoke the current browser session
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetCurrentUser Return the current authenticated user
	// (GET /api/v1/auth/me)
	GetCurrentUser(w http.ResponseWriter, r *http.Request)
	// Register Register an identity and create its first browser session
	// (POST /api/v1/auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// ListSessions List active sessions for the current user
	// (GET /api/v1/auth/sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// RevokeSession Revoke one active session owned by the current user
	// (DELETE /api/v1/auth/sessions/{sessionId})
	RevokeSession(w http.ResponseWriter, r *http.Request, sessionId openapi_types.UUID)
	// ConfirmTOTP Confirm pending TOTP and issue one-time recovery codes
	// (POST /api/v1/auth/totp/confirm)
	ConfirmTOTP(w http.ResponseWriter, r *http.Request)
	// DisableTOTP Disable TOTP after password and authenticator verification
	// (POST /api/v1/auth/totp/disable)
	DisableTOTP(w http.ResponseWriter, r *http.Request)
	// SetupTOTP Generate an encrypted pending TOTP credential
	// (POST /api/v1/auth/totp/setup)
	SetupTOTP(w http.ResponseWriter, r *http.Request)
	// ListCategories List owned income and expense categories
	// (GET /api/v1/categories)
	ListCategories(w http.ResponseWriter, r *http.Request, params ListCategoriesParams)
	// CreateCategory Create a category and its private ledger account atomically
	// (POST /api/v1/categories)
	CreateCategory(w http.ResponseWriter, r *http.Request)
	// UpdateCategory Rename, archive, or restore an owned category
	// (PATCH /api/v1/categories/{categoryId})
	UpdateCategory(w http.ResponseWriter, r *http.Request, categoryId CategoryId)
	// GetLiveness Confirm that the API process is running
	// (GET /api/v1/health/live)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// GetReadiness Confirm that the API can serve database-backed requests
	// (GET /api/v1/health/ready)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// CompleteOnboarding Save settings, first account, opening balance, and optional recurring income atomically
	// (POST /api/v1/onboarding/complete)
	CompleteOnboarding(w http.ResponseWriter, r *http.Request)
	// PrepareReconciliation Preview in CONFIRM mode or atomically apply in AUTO mode
	// (POST /api/v1/reconciliation/prepare)
	PrepareReconciliation(w http.ResponseWriter, r *http.Request)
	// ConfirmReconciliation Revalidate a reconciliation preview and apply it atomically
	// (POST /api/v1/reconciliation/previews/{previewId}/confirm)
	ConfirmReconciliation(w http.ResponseWriter, r *http.Request, previewId PreviewId)
	// GetReconciliationStatus Return the reminder window and per-account completion for one month
	// (GET /api/v1/reconciliation/status)
	GetReconciliationStatus(w http.ResponseWriter, r *http.Request, params GetReconciliationStatusParams)
	// ListRecurringTemplates List owned recurring operation templates
	// (GET /api/v1/recurring-templates)
	ListRecurringTemplates(w http.ResponseWriter, r *http.Request, params ListRecurringTemplatesParams)
	// CreateRecurringTemplate Create a typed recurring operation template
	// (POST /api/v1/recurring-templates)
	CreateRecurringTemplate(w http.ResponseWriter, r *http.Request)
	// UpdateRecurringTemplate Edit, pause, resume, archive, or restore a recurring template
	// (PATCH /api/v1/recurring-templates/{templateId})
	UpdateRecurringTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// ListTransactions List immutable operations using stable cursor pagination
	// (GET /api/v1/transactions)
	ListTransactions(w http.ResponseWriter, r *http.Request, params ListTransactionsParams)
	// CreateTransaction Post one typed financial operation as a balanced transaction
	// (POST /api/v1/transactions)
	CreateTransaction(w http.ResponseWriter, r *http.Request)
	// ReplaceTransaction Atomically reverse an operation and post its corrected replacement
	// (POST /api/v1/transactions/{transactionId}/replacement)
	ReplaceTransaction(w http.ResponseWriter, r *http.Request, transactionId TransactionId)
	// ReverseTransaction Preserve and reverse an owned posted transaction
	// (POST /api/v1/transactions/{transactionId}/reversal)
	ReverseTransaction(w http.ResponseWriter, r *http.Request, transactionId TransactionId)
	// DeleteAccount Permanently delete the user and all owned data after password confirmation
	// (DELETE /api/v1/users/me)
	DeleteAccount(w http.ResponseWriter, r *http.Request)
	// UpdateProfile Update display name or email with password confirmation for email changes
	// (PATCH /api/v1/users/me)
	UpdateProfile(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change password and revoke all other sessions
	// (PUT /api/v1/users/me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// UpdateUserSettings Update timezone, currencies, and reconciliation preference
	// (PATCH /api/v1/users/me/settings)
	UpdateUserSettings(w http.ResponseWriter, r *http.Request)
}

